package factories

import (
	"context"
	"database/sql"
	"deploycrate-ce/internal/storage"
	"deploycrate-ce/models"
	"fmt"
	"time"

	"github.com/go-faker/faker/v4"
	"github.com/google/uuid"
)

// Factory declarations below are generated by Andurel.

type UserFactory struct {
	models.UserEntity
}

type UserOption func(*UserFactory)

func BuildUser(opts ...UserOption) models.UserEntity {
	f := &UserFactory{
		UserEntity: models.UserEntity{
			Email:            faker.Word(),
			EmailValidatedAt: sql.NullTime{Time: time.Now(), Valid: true},
			Password:         []byte{},
			IsAdmin:          randomBool(),
		},
	}

	for _, opt := range opts {
		opt(f)
	}

	return f.UserEntity
}

func CreateUser(
	ctx context.Context,
	exec storage.Executor,
	opts ...UserOption,
) (models.UserEntity, error) {
	built := BuildUser(opts...)

	entity := models.UserEntity{
		ID:               uuid.New(),
		CreatedAt:        time.Now(),
		UpdatedAt:        time.Now(),
		Email:            built.Email,
		EmailValidatedAt: built.EmailValidatedAt,
		Password:         built.Password,
		IsAdmin:          built.IsAdmin,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.UserEntity{}, err
	}

	return entity, nil
}

func CreateUsers(
	ctx context.Context,
	exec storage.Executor,
	count int,
	opts ...UserOption,
) ([]models.UserEntity, error) {
	users := make([]models.UserEntity, 0, count)

	for i := range count {
		entity, err := CreateUser(ctx, exec, opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create user %d: %w", i+1, err)
		}
		users = append(users, entity)
	}

	return users, nil
}

func WithUsersEmail(value string) UserOption {
	return func(f *UserFactory) {
		f.UserEntity.Email = value
	}
}

func WithUsersEmailValidatedAt(value sql.NullTime) UserOption {
	return func(f *UserFactory) {
		f.UserEntity.EmailValidatedAt = value
	}
}

func WithUsersPassword(value []byte) UserOption {
	return func(f *UserFactory) {
		f.UserEntity.Password = value
	}
}

func WithUsersIsAdmin(value bool) UserOption {
	return func(f *UserFactory) {
		f.UserEntity.IsAdmin = value
	}
}

func WithEmail(email string) UserOption {
	return func(f *UserFactory) {
		f.Email = email
	}
}

func WithIsAdmin(isAdmin bool) UserOption {
	return func(f *UserFactory) {
		f.IsAdmin = isAdmin
	}
}

func WithEmailValidatedAt(t time.Time) UserOption {
	return func(f *UserFactory) {
		f.EmailValidatedAt = sql.NullTime{Time: t, Valid: true}
	}
}

func WithValidatedEmail() UserOption {
	return WithEmailValidatedAt(time.Now())
}

func WithPassword(password []byte) UserOption {
	return func(f *UserFactory) {
		f.Password = password
	}
}
